{
  "passageId": "law-interpretation-guarantee",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "법의 보편적 적용 성격을 이유로 일상적 의미에 충실하게 해석해야 한다는 당위를 뒷받침한다."
    },
    {
      "id": "R2",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "일상적 의미에 충실한 해석을 ‘문리 해석’이라고 명명하고 법 해석에서의 지위를 밝힌다."
    },
    {
      "id": "R3",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "문리 해석만으로 내용을 파악하기 어렵다는 한계에 대해 체계적·역사적 해석이라는 대안을 제시한다."
    },
    {
      "id": "R4",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 해석 방법을 의미 파악의 기준에 따라 사용 맥락과 입법 과정의 논의로 구별한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "구조물의 안전을 담보한다는 표현이 담보의 일상적 의미를 보여 주는 사례이다."
    },
    {
      "id": "R6",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "담보라는 표현의 의미를 일상적 사용과 성문법 조문에서의 사용이라는 서로 다른 경우에 따라 대비한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보가 법적 맥락에 따라 다르게 해석된다는 설명을 유상 계약과 매매의 사례로 구체화한다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보의 맥락적 의미를 채권 및 담보 물권의 사례로 구체화한다."
    },
    {
      "id": "R9",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "같은 담보의 의미가 유상 계약에서는 값어치 보장이고 채권에서는 실현 가능성 보장이라는 차이를 보인다."
    },
    {
      "id": "R10",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "계약 당시 하자에 대한 담보 책임 원칙에 매수인이 하자를 알았거나 알 수 있었던 경우의 예외를 제시한다."
    },
    {
      "id": "R11",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "손해 배상이라는 원칙에 대해 계약 목적을 달성할 수 없을 때에는 계약 파기도 가능하다는 예외를 제시한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "계약을 파기할 수 있다는 구제 내용을 대금 환불 청구까지 덧붙여 구체화한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "돈을 받아야 금전 채권이 실현된다는 사실이 미지급 시 강제 집행을 거쳐야 한다는 설명의 근거가 된다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "강제 집행을 통한 채권 실현을 목적물이 부동산인 경우의 경매와 배당으로 구체화한다."
    },
    {
      "id": "R15",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "채권액에 비례한 배당 원칙에 대해 담보 물권자의 우선 배당이라는 예외를 제시한다."
    },
    {
      "id": "R16",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "담보 물권자의 우선 배당은 채권 실현 가능성을 보장하는 담보의 기능을 구체적으로 보여 주는 사례이다."
    },
    {
      "id": "R17",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "채권 실현 가능성을 보장한다는 담보의 기능을 보증이라는 다른 제도에 가져다 적용한다."
    },
    {
      "id": "R18",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "보증이 담보 기능을 수행한다는 성격으로부터 주채무 소멸 시 보증 채무도 소멸한다는 법적 설명을 도출한다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "보증인에게만 채무를 발생시킨다는 사실이 보증 계약은 유상 계약이 아니라는 판단을 뒷받침한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "당사자 간 상호 대가 약속이라는 유상 계약의 정의가 보증 계약의 해당 여부를 판단하는 근거가 된다."
    },
    {
      "id": "R21",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "별도의 대가 지급 계약이 있더라도 보증 계약 자체는 유상 계약이 아니라는 점을 밝힌다."
    },
    {
      "id": "R22",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "보증인 보호를 위한 법적 규제를 민법상 형식 요건과 무효 주장 제한으로 구체화한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "보증인 보호 규제의 내용을 특별법의 적용 요건과 보증 기간 간주 규정으로 구체화한다."
    },
    {
      "id": "R24",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "형식 요건을 위반한 계약은 무효이지만 채무 이행 후에는 그 무효를 주장할 수 없다는 한계를 제시한다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "보증 기간이 명시되지 않으면 3년으로 간주한다는 규정이 특별법상 보호의 구체적인 예이다."
    },
    {
      "id": "R26",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "보증인에게 이행 거절 권리가 있다는 원칙에 대해 연대 보증 특약으로 이를 포기할 수 있다는 예외를 제시한다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "특약으로 이행 거절 권리를 포기했다는 내용에서 연대 보증인은 직접적인 전액 지급 청구도 거절할 수 없다는 결론이 나온다."
    },
    {
      "id": "R28",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "특별법의 보증인 보호 내용을 설명한 데서 연대 보증인에게도 적용되는지 묻는 논의로 확장한다."
    },
    {
      "id": "R29",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "연대 보증인의 특성을 설명한 뒤 특별법 적용 여부라는 새로운 쟁점으로 논의를 옮긴다."
    },
    {
      "id": "R30",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "하나의 법률 안에서 적용 대상을 규정한 조문 문구와 연대 보증인 보호를 강조한 입법 취지가 어긋날 수 있음을 제시한다."
    },
    {
      "id": "R31",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "조문 문구와 입법 과정의 강조점 차이가 해석 방법에 따라 적용 여부의 결론이 달라질 수 있다는 판단의 근거이다."
    },
    {
      "id": "R32",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "입법 과정의 논의를 고려하는 역사적 해석을 특별법의 연대 보증인 보호 취지라는 구체적 사안에 적용한다."
    },
    {
      "id": "R33",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "조문 표현의 의미에서 출발하는 문리 해석을 특별법 제2조의 보증 계약 규정에 적용한다."
    }
  ]
}

